<?php
require __DIR__.'/../../app/Services/SeoExpert/SeoRecommendationReview.php';
require __DIR__.'/../../app/Services/AI/ArticleGenerator.php';
require __DIR__.'/../../app/Services/Seo/SeoMonthlyReportService.php';
$n=0;function check($ok,$label){global $n;if(!$ok)throw new RuntimeException($label);$n++;echo "PASS $label\n";}
$facts=['business_facts'=>'Local guides and private Egypt tours.','audience'=>'Families who want free cancellation and licensed guides.','offers'=>'One Luxor product: Children travel free.'];
$review=fn($text,$f=null)=>SeoClaimEvidence::review(['content'=>$text],$f??$facts);
foreach(['Explore tours with licensed Egyptologist guides.','Private trips with certified tour guides.','Book with free cancellation.','Cancellation is free.','Cancel free of charge.','Children under 6 travel free.','Children aged 6 to 11 receive a 50 percent rate reduction.','Children get 50% off.','إلغاء مجاني لكل الرحلات.','رحلات مع مرشدين مرخصين.','الأطفال يحصلون على خصم 50%.'] as $text)check($review($text)['state']==='needs_confirmation','unsupported claim flagged: '.$text);
check($review('Explore the published tour routes with local guides.')['state']==='no_flagged_claims','ordinary factual prose remains supported');
check($review('Is cancellation free?')['state']==='no_flagged_claims','a genuine confirmation question is not asserted as fact');
check($review('Confirm free cancellation with the operator before booking.')['state']==='no_flagged_claims','confirmation guidance remains possible');
check($review('Confirm the itinerary. Free cancellation for all tours.')['state']==='needs_confirmation','confirmation prefix cannot hide a later assertion');
check($review('Children travel free.')['state']==='needs_confirmation','a single product offer does not prove a general children policy');
check($review('Book with free cancellation.',['business_facts'=>'No free cancellation is offered.'])['state']==='needs_confirmation','negated fact cannot confirm affirmative policy');
check($review('Free cancellation.',['business_facts'=>'Free cancellation?'])['state']==='needs_confirmation','question in confirmed facts cannot become affirmative evidence');
check($review('Free cancellation.',['business_facts'=>'Confirm free cancellation.'])['state']==='needs_confirmation','request for confirmation is not evidence');
check($review('All tours include licensed guides.',['business_facts'=>'The Luxor tour includes licensed guides.'])['state']==='needs_confirmation','one tour credential cannot become all-tour claim');
$confirmed=['business_facts'=>'Book with free cancellation. Children under 6 travel free. Explore tours with licensed Egyptologist guides.'];
check($review('Book with free cancellation.',$confirmed)['state']==='no_flagged_claims','exact confirmed policy with same scope is permitted');
check($review('**CHILDREN UNDER 6 TRAVEL FREE.**',$confirmed)['state']==='no_flagged_claims','case and formatting do not change an exact statement');
check($review('Explore tours with licensed Egyptologist guides.',$confirmed)['state']==='no_flagged_claims','exact confirmed credentials are permitted');
check($review('Children under 8 travel free.',$confirmed)['state']==='needs_confirmation','changed child age requires new confirmation');
check($review('Book with free cancellation.',['business_facts'=>'Book with free cancellation only until 48 hours before departure.'])['state']==='needs_confirmation','dropping a cancellation limitation cannot pass as exact evidence');
$brief=['confirmed_facts'=>$facts];
foreach(['title','meta_description','content'] as $field)check(ArticleGenerator::validateBriefOutput([$field=>'Book with free cancellation.'],$brief)!==null,'article '.$field.' uses same evidence guard');
check(ArticleGenerator::validateBriefOutput(['faqs'=>[['question'=>'What is the policy?','answer'=>'Children travel free.']]],$brief)!==null,'FAQ answer cannot bypass policy guard');
check(ArticleGenerator::validateBriefOutput(['content'=>'Book with free cancellation.'],['confirmed_facts'=>$confirmed])===null,'confirmed article remains publishable');
$page=['url'=>'https://example.com/tours','h1'=>'All Tours','title'=>'Tours','description'=>''];
$task=['kind'=>'metadata','status'=>'pending','field_name'=>'description','page_url'=>$page['url'],'expected_value'=>'Explore Egypt tours with licensed Egyptologist guides and free cancellation for your next trip.'];
$a=SeoRecommendationReview::assess($task,[$page],$facts);
check($a['state']==='reviewable'&&$a['claim_review']['state']==='needs_confirmation','unsafe pending proposal stays editable and gains separate factual review');
$task['status']='verified';$task['is_active']=1;
$a=SeoRecommendationReview::assess($task,[$page],$facts);
check($a['state']==='retained'&&$a['claim_review']['state']==='needs_confirmation','applied history does not suppress factual warning');
$task['recommendation_review']=$a;
check(SeoTaskFollowUp::forTask($task)['state']==='verified','technical verification remains distinct from factual review');
check(SeoClaimEvidence::snapshotFacts(['brief'=>['business_facts'=>'Free cancellation.']])===[],'legacy unshared briefs cannot become confirmed evidence');
check(SeoClaimEvidence::snapshotFacts(['brief'=>['shared_profile'=>['version'=>1,'needs_reconfirmation'=>true,'facts'=>$confirmed]]])===[],'profile needing confirmation supplies no authoritative claims');
check(SeoPlanQualityGate::filterChanges([['page_index'=>0,'field'=>'description','value'=>$task['expected_value']]],[$page],'',$facts)===[],'new metadata generation filters unsupported commercial claims');
$task['status']='pending';$task['is_active']=0;unset($task['recommendation_review']);$task['title']='Review tour summary';$task['instructions']='Review the proposed summary.';
$task['snapshot_json']=json_encode(['brief'=>['shared_profile'=>['version'=>1,'facts'=>$facts]],'pages'=>[$page]]);
$report=SeoMonthlyReportService::followUpPlan([$task]);
check($report['next_plan'][0]['follow_up']['state']==='needs_confirmation','monthly next plan explains factual confirmation');
$html=SeoMonthlyReportService::html(SeoMonthlyReportService::assemble($report,['start'=>'2026-09-01','end'=>'2026-09-30']),'example.com');
check(str_contains($html,'أكد السياسة'),'monthly HTML includes the concrete evidence action');
echo "$n assertions passed\n";
